mapper.select:
SELECT ROWNUM NUM, X.STATUS_TEXT, X.BUYER_NAME, X.BEFORE_GR_DATE, X.PO_NO, X.BUYER_ITEM_NO, X.DESCRIPTION, X.MAKER_NAME, X.UNIT_PRICE, X.ITEM_QTY, X.REQ_USER_NAME, X.REQ_USER_DEPT_NAME, X.REQ_USER_TEL_NO, X.AGENT_NAME, X.AGENT_USER_NAME, X.AGENT_TEL_NO, X.KEP_USER_NAME, X.SPECIFICATION, X.ORIGIN_NAME, X.AGENT_PRICE, X.UNIT_MEASURE, X.BS_NO, X.BUYER_CODE, X.STATUS, X.CLOSE_ITEM_QTY, X.DELIVERY_FLAG, X.PROCESS_TYPE, X.PROCESS_NAME, X.WAREHOUSE_CODE, X.WAREHOUSE_NAME, X.DELY_TO_LOCATION, X.REQ_USER_ID, X.REQ_USER_DEPT_CODE, X.MAKER_CODE, X.ORIGIN_CODE, X.AGENT_CODE, X.AGENT_USER_ID, X.KEP_USER_ID, X.CONTRACT_NO, X.CONTRACT_SEQ, X.REMARK, X.INV_NO, X.ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = X.ADD_USER_ID) AS ADD_USER_NAME FROM ( SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=A.BUYER) AS BUYER_NAME, A.BEFORE_GR_DATE AS BEFORE_GR_DATE, A.PO_NO AS PO_NO, A.BUYER_ITEM_NO AS BUYER_ITEM_NO, A.DESCRIPTION AS DESCRIPTION, A.MAKER_NAME AS MAKER_NAME, A.UNIT_PRICE AS UNIT_PRICE, A.ITEM_QTY, A.REQ_USER_NAME, A.REQ_USER_DEPT_NAME, A.REQ_USER_TEL_NO, A.AGENT_NAME, A.AGENT_USER_NAME, A.AGENT_TEL_NO, A.KEP_USER_NAME, A.SPECIFICATION, A.ORIGIN_NAME, A.AGENT_PRICE, A.UNIT_MEASURE, A.BS_NO, A.BUYER AS BUYER_CODE, A.CLOSE_ITEM_QTY, A.DELIVERY_FLAG, A.PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND FLAG = 'Y' AND CODE = A.PROCESS_TYPE) AS PROCESS_NAME, A.WAREHOUSE_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.WAREHOUSE_CODE) AS WAREHOUSE_NAME, A.DELY_TO_LOCATION, A.REQ_USER_ID, A.REQ_USER_DEPT_CODE, A.MAKER_CODE, A.ORIGIN_CODE, A.AGENT_CODE, A.AGENT_USER_ID, A.KEP_USER_ID, A.CONTRACT_NO, A.CONTRACT_SEQ, A.REMARK, B.INV_NO, CASE WHEN A.STATUS = 'D' THEN 'BS99' --'선입고취소' WHEN A.DELIVERY_FLAG = 'Y' THEN 'BS40' --'납품확정' WHEN A.DELIVERY_FLAG = 'P' THEN 'BS30' --'납품예정' WHEN B.INV_NO IS NOT NULL THEN 'BS20' --'송장' WHEN B.INV_NO IS NULL THEN 'BS10' --'요청' ELSE NULL END AS STATUS, CASE WHEN A.STATUS = 'D' THEN '선입고취소' WHEN A.DELIVERY_FLAG = 'Y' THEN '납품확정' WHEN A.DELIVERY_FLAG = 'P' THEN '납품예정' WHEN B.INV_NO IS NOT NULL THEN '송장' WHEN B.INV_NO IS NULL THEN '요청' ELSE NULL END AS STATUS_TEXT, A.ADD_USER_ID FROM KEP_BEFORE_STOCKED_MNG A , KEP_BEFORE_STOCKED_IVDT B WHERE A.BEFORE_GR_DATE >= #{st_from_date} AND A.BEFORE_GR_DATE <= #{st_to_date} AND A.BUYER = B.BUYER(+) AND A.BS_NO = B.BS_NO(+)
AND A.BUYER IN
#{itm}
AND A.BUYER_ITEM_NO = #{st_buyer_item_no}
AND A.PROCESS_TYPE = #{st_process_type}
AND (A.DESCRIPTION LIKE '%' || #{st_desc_spec} || '%' OR A.SPECIFICATION LIKE '%' || #{st_desc_spec} || '%')
AND A.PO_NO IS NOT NULL
ORDER BY A.BUYER, A.BS_NO DESC ) X
WHERE X.STATUS = #{st_status_code}

mapper.update:

UPDATE KEP_BEFORE_STOCKED_MNG SET
	  STATUS='D'
	, CHANGE_DATE  = TO_CHAR(SYSDATE,'YYYYMMDD')    
    , CHANGE_TIME  = TO_CHAR(SYSDATE,'HH24MISS')
WHERE BUYER = #{BUYER_CODE}
	AND BS_NO = #{BS_NO}

mapper.select:

SELECT  COM_TYPE
FROM ICOMCMPY
WHERE COM_CODE = #{BUYER_CODE}
